mapper.sql:
WITH exception_facts AS ( SELECT 'SORTING_DIFFERENCE'::text AS exception_type, t.id AS source_id, i.id AS source_row_id, t.task_no AS source_no, i.sales_order_id AS order_id, i.order_no_snapshot AS order_no, i.customer_name_snapshot AS customer_name, t.warehouse_id, t.warehouse_name_snapshot AS warehouse_name, i.product_name_snapshot AS product_name, i.sale_unit_snapshot AS unit, i.planned_quantity_snapshot AS planned_quantity, i.sorted_quantity AS actual_quantity, i.sorted_quantity - i.planned_quantity_snapshot AS difference_quantity, i.result AS source_status, i.reason, i.sorted_at AS occurred_at FROM sorting_task_item i JOIN sorting_task t ON t.id = i.task_id AND t.deleted = FALSE WHERE i.deleted = FALSE AND i.occupation_status = 'ACTIVE' AND i.sorted_quantity IS NOT NULL AND i.sorted_quantity != i.planned_quantity_snapshot AND i.sorted_at >= #{startAt} AND i.sorted_at < #{endAt}
UNION ALL SELECT 'DELIVERY_EXCEPTION', d.id, a.id, d.route_no, a.order_id, a.order_no_snapshot, s.customer_name_snapshot, d.warehouse_id, d.warehouse_name_snapshot, NULL::text, NULL::text, NULL::numeric, NULL::numeric, NULL::numeric, a.fulfillment_status, a.sign_reason, a.signed_at FROM delivery_route_order a JOIN delivery_route d ON d.id = a.route_id AND d.deleted = FALSE JOIN delivery_route_stop s ON s.id = a.stop_id AND s.deleted = FALSE WHERE a.deleted = FALSE AND a.assignment_status = 'ACTIVE' AND a.fulfillment_status = 'EXCEPTION' AND a.signed_at >= #{startAt} AND a.signed_at < #{endAt}
AND FALSE
AND d.driver_id IN #{driver}
UNION ALL SELECT 'RETURN_REJECTED', r.id, r.id, r.return_no, o.id, o.order_no, o.customer_name_snapshot, NULL::bigint, NULL::text, NULL::text, NULL::text, NULL::numeric, NULL::numeric, NULL::numeric, r.status, r.decision_reason, r.rejected_at FROM order_return r JOIN sales_order o ON o.id = r.order_id AND o.deleted = FALSE WHERE r.deleted = FALSE AND r.status = 'REJECTED' AND r.rejected_at >= #{startAt} AND r.rejected_at < #{endAt}
AND FALSE
AND o.seller_id IN #{seller}
), filtered AS ( SELECT * FROM exception_facts WHERE 1 = 1
AND FALSE
AND exception_type IN #{type}
AND exception_type = #{q.exceptionType} AND warehouse_id = #{q.warehouseId}
AND (source_no ILIKE CONCAT('%', #{q.keyword}, '%') OR order_no ILIKE CONCAT('%', #{q.keyword}, '%') OR customer_name ILIKE CONCAT('%', #{q.keyword}, '%') OR product_name ILIKE CONCAT('%', #{q.keyword}, '%'))
)
